import{_ as l,l as o,o as e,c as i,v as r,p as n,x as t,d as u,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Kruskal 重构树","description":"","frontmatter":{"title":"Kruskal 重构树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kruskal-reconstruction.md","filePath":"cs/kruskal-reconstruction.md","lastUpdated":1789023840000}'),p={name:"cs/kruskal-reconstruction.md"};function k(h,a,E,m,_,A){const s=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="kruskal-重构树" tabindex="-1">Kruskal 重构树 <a class="header-anchor" href="#kruskal-重构树" aria-label="Permalink to &quot;Kruskal 重构树&quot;">​</a></h1><div class="epigraph"><p>按边权从小到大做 Kruskal，每次连通两棵树就新建一个点当父亲、权记在该点上；原图路径的最大边，变成重构树上 LCA 的权。</p><footer>—— 据 Kruskal, 1956 的加边过程；重构树为 MST 上的标准派生结构整理</footer></div><p>上一课<a href="/cs/centroid-decomposition">点分治</a>按重心切树。主干<a href="/cs/mst-kruskal-prim">Kruskal 与 Prim</a>已用并查集按权加边。缺口是把加边历史<strong>树化</strong>：Kruskal 重构树。查询「\\(u\\) 到 \\(v\\) 路径上的最大边权」（瓶颈路）变成 LCA，不再每次从原图走。不重证切分定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向图，路径瓶颈 = 路径上最大边的最小可能（所有路径取 min-max）。最小生成树上的 \\(u\\)–\\(v\\) 路径即给出该瓶颈（唯一性不必：MST 路径是一组瓶颈最优）。重构：叶子是原顶点。边权升序，若两端不连通，新建节点 \\(p\\)，权为该边权，<code>parent[find(u)]=parent[find(v)]=p</code>。最终一棵二叉树形（森林）的有根树，内部点对应 MST 边。</p><p>\\(lca(u,v)\\) 的权 = \\(u\\)–\\(v\\) 的瓶颈。子树 = 「只用不大于该权的边能连通的点集」。缺口是这张树，不是再跑 Kruskal 求整棵 MST 权。</p><h3 id="不是-steiner-树" tabindex="-1">不是 steiner 树 <a class="header-anchor" href="#不是-steiner-树" aria-label="Permalink to &quot;不是 steiner 树&quot;">​</a></h3><p>内部点是虚拟的，不在原图。深度可按加入顺序，单调。查询连通性：两点在权 \\(\\le x\\) 下连通 \\(\\Leftrightarrow\\) LCA 权 \\(\\le x\\)，或把权当深度做倍增。</p><p><span class="marginnote">结构随 Kruskal 过程自然出现，无单独必引论文时引 Kruskal 1956 与并查集。最大生成树把权取负，瓶颈改成路径最小边。后课 Borůvka 与次小生成树仍在 MST 家族，不走重构查询。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>边排序；并查集维护当前树根。新建 \\(O(n)\\) 个内部点。对重构树做 LCA / 倍增。注意并查集的 <code>find</code> 要连到当前真实树根（虚拟点）。</p>',11)),(e(),n(c,null,{default:t(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E8%BE%B9%E6%8C%89%E6%9D%83%E6%8E%92%E5%BA%8F%22%5D%20--%3E%20K%5B%22Kruskal%20%E5%8A%A0%E8%BE%B9%22%5D%0A%20%20K%20--%3E%20P%5B%22%E6%96%B0%E5%BB%BA%E7%82%B9%E5%BD%93%E7%88%B6%E4%BA%B2%22%5D%0A%20%20P%20--%3E%20T%5B%22%E9%87%8D%E6%9E%84%E6%A0%91%22%5D%0A%20%20T%20--%3E%20B%5B%22LCA%20%E6%9D%83%20%3D%20%E8%B7%AF%E5%BE%84%E7%93%B6%E9%A2%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不连通则森林，跨树询问无路径。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kruskal 加入的边是当时连接两连通块的最轻边，故该边权等于两块之间的瓶颈。LCA 正是合并 \\(u\\)、\\(v\\) 所在块的那一次，权即瓶颈。与点分治不同：这里树的形状由边权决定，用来回答与权阈值相关的连通，不是任意距离计数。</p><p>Prim 的生长序一般不直接给出同一 LCA 语义，本课用 Kruskal。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写次小生成树（下一课）、不写有向最小树形图。动态边权要用 LCT 维护 MST，重构树静态。后课默认：瓶颈路 = MST 路径 = 重构树 LCA。下一课 Borůvka 并行长树，以及次小生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kruskal 加边史变成有根树；LCA 权是瓶颈。</li><li>阈值连通 = 内部点权比较。</li><li>静态无向图；与重心分治分工不同。</li><li>出处：Kruskal, 1956；并查集见 CLRS 第 21 章。</li></ul>',8))])}const T=l(p,[["render",k]]);export{f as __pageData,T as default};
